type Props = {
	// Syntax-highlighted HTML pre-rendered by shiki when the site was archived.
	html: string;
};

export default function CodeBlock({ html }: Props) {
	return (
		<pre
			className="h-full w-full p-2 bg-gray-50 rounded-lg border border-gray-300 whitespace-pre-wrap break-words"
			// Trusted HTML generated by shiki when the site was archived.
			dangerouslySetInnerHTML={{ __html: html }}
		/>
	);
}
